-- 세트 340: 도커 자원 제한과 컨테이너 보안 기본 실습: --memory, --cpus, --pids-limit, update, --read-only, --tmpfs, --user, --cap-drop
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_docker_limits_security_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (340, 1, '메모리 상한을 걸고 컨테이너 띄우기', '컨테이너 `web` 을 백그라운드로 띄우되 메모리를 **64MB** 까지만 쓰게 제한하세요. (`alpine` 이미지에서 `sleep 300` 을 실행)', '`docker run` 에는 메모리 상한 옵션이 있어요. 단위는 `m`(메가바이트), `g`(기가바이트) 를 붙입니다. 확인은 `docker inspect` 의 HostConfig 항목에서 해요.', 'docker run -d --name web --memory 64m alpine sleep 300
docker inspect -f ''{{.HostConfig.Memory}}'' web

# 64m = 64*1024*1024 = 67108864 바이트로 저장된다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.State.Running}}'' web)\\" = true ] ) && ( [ \\"$(docker inspect -f ''{{.HostConfig.Memory}}'' web)\\" = 67108864 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "web 이 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' web)\\" = true ]"]}, {"label": "메모리 상한이 64MB 다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.Memory}}'' web)\\" = 67108864 ]"]}]', '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]'),
  (340, 2, 'CPU 를 절반만 쓰게 제한하기', '컨테이너 `calc` 를 백그라운드로 띄우되 CPU 를 **0.5 코어** 까지만 쓰게 제한하세요. (`alpine` 이미지에서 `sleep 300` 을 실행)', '`docker run` 의 CPU 제한 옵션은 소수로 코어 수를 받아요. 확인은 HostConfig 의 `NanoCpus` 항목(10억 분의 1 코어 단위)으로 합니다.', 'docker run -d --name calc --cpus 0.5 alpine sleep 300
docker inspect -f ''{{.HostConfig.NanoCpus}}'' calc

# 0.5 코어 = 500000000 (1코어 = 1000000000)', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.State.Running}}'' calc)\\" = true ] ) && ( [ \\"$(docker inspect -f ''{{.HostConfig.NanoCpus}}'' calc)\\" = 500000000 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "calc 가 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' calc)\\" = true ]"]}, {"label": "CPU 상한이 0.5 코어다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.NanoCpus}}'' calc)\\" = 500000000 ]"]}]', '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]'),
  (340, 3, '프로세스 개수 제한하기', '컨테이너 `forky` 를 백그라운드로 띄우되 안에서 만들 수 있는 프로세스(스레드 포함)를 **50개** 까지로 제한하세요. (`alpine` 이미지에서 `sleep 300` 을 실행)', '프로세스 폭주(fork bomb)를 막는 옵션이 `docker run` 에 있어요. 이름에 `pids` 가 들어갑니다. 확인은 HostConfig 의 `PidsLimit` 항목입니다.', 'docker run -d --name forky --pids-limit 50 alpine sleep 300
docker inspect -f ''{{.HostConfig.PidsLimit}}'' forky

# 한도를 넘으면 fork 가 ''Resource temporarily unavailable'' 로 실패한다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.State.Running}}'' forky)\\" = true ] ) && ( [ \\"$(docker inspect -f ''{{.HostConfig.PidsLimit}}'' forky)\\" = 50 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "forky 가 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' forky)\\" = true ]"]}, {"label": "PID 상한이 50 이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.PidsLimit}}'' forky)\\" = 50 ]"]}]', '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]'),
  (340, 4, '걸려 있는 메모리 제한 읽어서 저장하기', '컨테이너 `capped` 가 메모리 제한을 건 채 실행 중입니다. 제한값을 **바이트 숫자만** `/tmp/work/mem.txt` 에 저장하세요. (사람이 단위를 읽어 직접 쓰지 말고 도커에게 물어보세요)', '`docker inspect` 에 `-f` 와 템플릿을 주면 원하는 항목만 나와요. 메모리 제한은 HostConfig 아래에 있습니다. 결과를 `>` 로 파일에 넘기세요.', 'docker inspect -f ''{{.HostConfig.Memory}}'' capped > /tmp/work/mem.txt
cat /tmp/work/mem.txt

# 128m 은 134217728 바이트. 값이 0 이면 제한이 없다는 뜻', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name capped --memory 128m alpine sleep 300 >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/work/mem.txt)\\" = \\"$(docker inspect -f ''{{.HostConfig.Memory}}'' capped)\\" ] && [ \\"$(cat /tmp/work/mem.txt)\\" -gt 0 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일에 바이트 값이 들어 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/work/mem.txt)\\" = \\"$(docker inspect -f ''{{.HostConfig.Memory}}'' capped)\\" ] && [ \\"$(cat /tmp/work/mem.txt)\\" -gt 0 ]"]}]', '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]'),
  (340, 5, '메모리를 넘겨 쓰면 컨테이너는 어떻게 될까', '`--memory 64m --memory-swap 64m` 으로 띄운 컨테이너 안의 프로그램이 64MB 보다 훨씬 많은 메모리를 계속 요구합니다. 이때 일어나는 일로 맞는 것은?', '메모리 제한은 CPU 제한과 달리 "천천히 돌리기"로 해결되지 않아요. 확보할 수 없을 때 커널이 어떻게 하는지 떠올려 보세요. 종료 후 `docker inspect` 의 State 항목을 보면 흔적이 남습니다.', NULL, NULL, '[]', 'choice', '["프로세스가 느려질 뿐 계속 살아 있고, 부족한 메모리는 호스트에서 얼마든지 빌려 써서 컨테이너는 끝까지 실행된다", "도커가 제한을 자동으로 조금씩 늘려 주기 때문에 컨테이너는 아무 문제 없이 종료 코드 0 으로 정상 종료된다", "커널이 프로세스를 강제 종료(OOM kill)하고, 컨테이너는 종료 코드 137 로 끝나며 `State.OOMKilled` 가 true 가 된다", "컨테이너가 일시정지(paused)되어 다른 컨테이너가 메모리를 돌려줄 때까지 그대로 멈춘 채 기다린다"]', 2, '메모리는 CPU 와 달리 **압축할 수 없는 자원**이라, 상한을 넘으면 커널이 OOM killer 로 프로세스를 죽입니다. 주 프로세스가 죽으면 컨테이너는 종료 코드 137(128+SIGKILL 9)로 끝나고 `docker inspect -f ''{{.State.OOMKilled}}''` 가 true 를 알려 줘요. CPU 는 넘기면 느려지기만(throttle) 하는 것과 대비됩니다.', NULL, NULL, NULL, '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]'),
  (340, 6, '돌고 있는 컨테이너의 메모리 한도 올리기', '컨테이너 `grow` 가 메모리 **64MB** 제한으로 실행 중입니다. **지우고 다시 만들지 말고**, 같은 컨테이너의 한도를 **256MB** 로 올리세요. (처음에 `--memory` 만 줬기 때문에 한 번에 안 될 수 있어요. 오류 메시지를 읽어 보세요)', '`docker update` 로 실행 중인 컨테이너의 제한을 바꿀 수 있어요. 메모리 한도가 swap 한도보다 커지면 거부되니, 오류 메시지가 알려 주는 다른 옵션도 같은 줄에서 함께 올리세요.', 'docker update --memory 256m --memory-swap 256m grow
docker inspect -f ''{{.HostConfig.Memory}}'' grow

# 메모리와 swap 은 한 쌍이다. 한쪽만 올리면 거부된다. 컨테이너는 재시작되지 않는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name grow --memory 64m alpine sleep 300 >/dev/null 2>&1; docker inspect -f ''{{.Id}}'' grow > /tmp/work/id; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.State.Running}}'' grow)\\" = true ] ) && ( [ \\"$(docker inspect -f ''{{.HostConfig.Memory}}'' grow)\\" = 268435456 ] ) && ( [ \\"$(docker inspect -f ''{{.Id}}'' grow)\\" = \\"$(cat /tmp/work/id)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "grow 가 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' grow)\\" = true ]"]}, {"label": "메모리 상한이 256MB 다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.Memory}}'' grow)\\" = 268435456 ]"]}, {"label": "처음 만든 그 컨테이너다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.Id}}'' grow)\\" = \\"$(cat /tmp/work/id)\\" ]"]}]', '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]'),
  (340, 7, '루트 파일시스템을 읽기 전용으로', '컨테이너 `vault` 를 백그라운드로 띄우되 컨테이너 안에서 **파일을 만들 수 없게** (루트 파일시스템 읽기 전용) 하세요. (`alpine` 이미지에서 `sleep 300` 을 실행)', '`docker run` 에는 루트 파일시스템을 읽기 전용으로 마운트하는 옵션이 있어요. 띄운 뒤 `docker exec vault touch /probe` 로 써 보면 어떤 오류가 나는지 볼 수 있습니다.', 'docker run -d --name vault --read-only alpine sleep 300
docker exec vault touch /probe

# touch: /probe: Read-only file system', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.State.Running}}'' vault)\\" = true ] ) && ( [ \\"$(docker inspect -f ''{{.HostConfig.ReadonlyRootfs}}'' vault)\\" = true ] ) && ( ! docker exec vault touch /probe 2>/dev/null )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "vault 가 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' vault)\\" = true ]"]}, {"label": "읽기 전용 설정이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.ReadonlyRootfs}}'' vault)\\" = true ]"]}, {"label": "파일 쓰기가 막힌다", "cmd": ["sh", "-c", "! docker exec vault touch /probe 2>/dev/null"]}]', '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]'),
  (340, 8, '읽기 전용인데 /tmp 만 쓸 수 있게', '컨테이너 `scratch` 를 백그라운드로 띄우세요. 루트 파일시스템은 **읽기 전용**이지만 `/tmp` 에는 **파일을 쓸 수 있어야** 합니다. (`alpine` 이미지에서 `sleep 300` 을 실행)', '읽기 전용 옵션에 더해, 특정 경로에 메모리 기반 쓰기 공간을 붙이는 옵션이 있어요. 경로를 인자로 줍니다. `/tmp` 와 `/etc` 에 각각 `touch` 해서 비교해 보세요.', 'docker run -d --name scratch --read-only --tmpfs /tmp alpine sleep 300
docker exec scratch touch /tmp/probe
docker exec scratch touch /etc/probe

# /tmp 는 되고 /etc 는 막힌다. tmpfs 내용은 컨테이너가 사라지면 같이 사라진다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.State.Running}}'' scratch)\\" = true ] ) && ( [ \\"$(docker inspect -f ''{{.HostConfig.ReadonlyRootfs}}'' scratch)\\" = true ] ) && ( docker exec scratch touch /tmp/probe ) && ( ! docker exec scratch touch /etc/probe 2>/dev/null )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "scratch 가 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' scratch)\\" = true ]"]}, {"label": "읽기 전용 설정이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.ReadonlyRootfs}}'' scratch)\\" = true ]"]}, {"label": "/tmp 에는 쓸 수 있다", "cmd": ["sh", "-c", "docker exec scratch touch /tmp/probe"]}, {"label": "/etc 에는 쓸 수 없다", "cmd": ["sh", "-c", "! docker exec scratch touch /etc/probe 2>/dev/null"]}]', '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]'),
  (340, 9, 'root 가 아닌 사용자로 실행하기', '컨테이너 `worker` 를 백그라운드로 띄우되 프로세스가 root 가 아니라 **UID 1000, GID 1000** 으로 돌게 하세요. (`alpine` 이미지에서 `sleep 300` 을 실행)', '`docker run` 의 사용자 옵션은 `UID:GID` 형식을 받아요. 띄운 뒤 `docker exec worker id -u` 와 `id -g` 로 확인합니다.', 'docker run -d --name worker --user 1000:1000 alpine sleep 300
docker exec worker id -u
docker exec worker id -g

# 컨테이너 탈출·권한 상승 피해를 줄이는 기본 습관', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.State.Running}}'' worker)\\" = true ] ) && ( [ \\"$(docker exec worker id -u)\\" = 1000 ] ) && ( [ \\"$(docker exec worker id -g)\\" = 1000 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "worker 가 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' worker)\\" = true ]"]}, {"label": "UID 가 1000 이다", "cmd": ["sh", "-c", "[ \\"$(docker exec worker id -u)\\" = 1000 ]"]}, {"label": "GID 가 1000 이다", "cmd": ["sh", "-c", "[ \\"$(docker exec worker id -g)\\" = 1000 ]"]}]', '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]'),
  (340, 10, '권한(capability)을 다 빼고 필요한 것만 주기', '컨테이너 `locked` 를 백그라운드로 띄우세요. 리눅스 capability 를 **모두 제거**한 뒤 파일 소유자를 바꾸는 권한(**CHOWN**) 하나만 다시 허용합니다. root 로 돌아도 `chown` 만 되고 나머지 특수 권한은 없어야 해요. (`alpine` 이미지에서 `sleep 300` 을 실행)', '`docker run` 에는 capability 를 빼는 옵션과 더하는 옵션이 한 쌍으로 있어요. 먼저 전부 빼고(`ALL`), 그 다음 이름 하나를 더합니다. `docker exec locked chown 1:1 /etc/hostname` 으로 확인해 보세요.', 'docker run -d --name locked --cap-drop ALL --cap-add CHOWN alpine sleep 300
docker exec locked chown 1:1 /etc/hostname
docker exec locked grep CapEff /proc/1/status

# 최소 권한 원칙: 빼고(drop) 필요한 것만 더한다(add)', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.State.Running}}'' locked)\\" = true ] ) && ( docker inspect -f ''{{.HostConfig.CapDrop}}'' locked | grep -q ALL ) && ( docker exec locked chown 1:1 /etc/hostname ) && ( docker exec locked grep CapEff /proc/1/status | grep -q ''0000000000000001$'' )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "locked 가 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' locked)\\" = true ]"]}, {"label": "ALL 을 뺐다", "cmd": ["sh", "-c", "docker inspect -f ''{{.HostConfig.CapDrop}}'' locked | grep -q ALL"]}, {"label": "chown 은 된다", "cmd": ["sh", "-c", "docker exec locked chown 1:1 /etc/hostname"]}, {"label": "유효 권한이 CHOWN 하나뿐이다", "cmd": ["sh", "-c", "docker exec locked grep CapEff /proc/1/status | grep -q ''0000000000000001$''"]}]', '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]'),
  (340, 11, '권한 상승을 막는 보안 옵션', '컨테이너 안의 프로세스가 setuid 파일 등을 이용해 **새 권한을 얻지 못하게** 하는 `--security-opt` 값을 채우세요.', '`--security-opt` 의 값 중, 이름 그대로 "새 권한 금지"를 뜻하는 것을 고르세요. 나머지는 오히려 보호 장치를 끄는 값이에요.', NULL, NULL, '[]', 'fill', '["no-new-privileges", "seccomp=unconfined", "apparmor=unconfined", "label=disable"]', NULL, '`no-new-privileges` 는 프로세스와 자식이 setuid·파일 capability 로 권한을 더 얻지 못하게 막습니다(`/proc/<pid>/status` 의 `NoNewPrivs: 1`). 나머지 `seccomp=unconfined`, `apparmor=unconfined`, `label=disable` 은 기본 보호 장치를 **끄는** 값이라 보안을 약하게 만들어요.', '[0]', 'docker run -d --name app --security-opt {0} alpine sleep 300', NULL, '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]'),
  (340, 12, '제한을 걸고 확인하고 고치는 흐름', '컨테이너에 자원 제한을 걸고 검증한 뒤 조정하는 흐름을 **앞에서 뒤**로 놓으세요.', '먼저 제한을 걸어 띄우고 → 설정이 들어갔는지 읽고 → 실제 동작을 시험하고 → 부족하면 올리고 → 끝나면 정리하는 순서입니다.', NULL, NULL, '[]', 'order', '["`docker run -d --memory 64m --cpus 0.5 --pids-limit 50` 으로 제한을 걸어 컨테이너를 띄운다", "`docker inspect -f` 로 Memory, NanoCpus, PidsLimit 값이 의도대로인지 읽는다", "`docker exec` 로 실제 동작(쓰기 시도, `id -u` 등)을 시험해 본다", "부족하면 `docker update --memory ... --memory-swap ...` 로 재시작 없이 올린다", "쓰지 않는 컨테이너는 `docker rm -f` 로 지운다"]', NULL, '**run(제한) → inspect(설정 읽기) → exec(동작 시험) → update(조정) → rm(정리)** 순서입니다. 제한은 설정만 믿지 말고 `inspect` 로 값을, `exec` 로 동작을 함께 확인하고, 메모리는 `update` 로 재시작 없이 바꿀 수 있어요.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "Docker 공식 문서: Resource constraints (메모리·CPU 제한)", "url": "https://docs.docker.com/engine/containers/resource_constraints/"}, {"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker container update", "url": "https://docs.docker.com/reference/cli/docker/container/update/"}, {"title": "Docker 공식 문서: Docker Engine security", "url": "https://docs.docker.com/engine/security/"}]');
